mapper.select:
SELECT a.keeper_id, a.keeper_name, COUNT(CASE WHEN FALSE = ISNULL( a.sign_in_status ) AND a.sign_in_status <> '1' THEN 1 END) + COUNT(CASE WHEN FALSE = ISNULL( a.sign_out_status ) AND a.sign_out_status <> '4' THEN 1 END) + COUNT(CASE WHEN TRUE = ISNULL( a.sign_in_status ) AND NOW() > CONCAT( a.attendance_date, ' ', a.sign_in_time ) THEN 1 END) + COUNT(CASE WHEN TRUE = ISNULL( a.sign_out_status ) AND NOW() > CONCAT( a.attendance_date, ' ', a.sign_out_time ) THEN 1 END) AS dbnormal_count, COUNT( CASE WHEN a.sign_in_status = '1' THEN 1 END ) + COUNT( CASE WHEN a.sign_out_status = '4' THEN 1 END )AS normal_count, a.industry_code, a.app_ver_code, a.tenant_id, MAX( a.sign_in_add_time ) create_time, a.grid_id FROM bm_attendance_line a
LEFT JOIN bm_grid_keeper_ref b ON a.keeper_id = b.keeper_id AND a.grid_id = b.grid_id AND b.delete_flag = '0'
WHERE a.tenant_id = #{tenantId} AND a.industry_code = #{industryCode}
AND a.attendance_date >= #{startDate}
AND a.attendance_date <= #{endDate}
AND b.grid_id = #{gridId}
AND (a.keeper_id like concat('%',#{keeperName},'%') OR a.keeper_name like concat('%',#{keeperName},'%'))
GROUP BY a.keeper_id,a.grid_id ORDER BY a.create_time DESC

SELECT t.keeper_id,t.keeper_name,t.`date`,t.`time`,t.`status`,t.keeperId,t.industryCode,t.tenantId,t.sign_in_time,t.sign_out_time,t.type,t.grid_id FROM (
SELECT a.keeper_id,a.keeper_name,a.attendance_date AS `date`,
a.sign_in_time,a.sign_out_time,"1" as type,
IFNULL(DATE_FORMAT(a.sign_in_add_time, '%H:%i:%s'),'-') AS `time`,a.sign_in_status AS `status`,
a.keeper_id keeperId,
a.industry_code industryCode,
a.tenant_id tenantId,
a.grid_id
FROM bm_attendance_line a
WHERE a.keeper_id = #{keeperId} AND a.grid_id = #{gridId}

    ${dataScope}


    AND a.attendance_date >= #{startDate}


    AND a.attendance_date <= #{endDate}


    AND a.sign_in_status = #{status}


    AND a.sign_in_status = '3' AND a.sign_out_status = '6'

UNION ALL
SELECT a.keeper_id,a.keeper_name,a.attendance_date AS `date`,
a.sign_in_time,a.sign_out_time,'2' as type,
IFNULL(DATE_FORMAT(a.sign_out_add_time, '%H:%i:%s'),'-') AS `time`,a.sign_out_status AS `status`,
a.keeper_id keeperId,
a.industry_code industryCode,
a.tenant_id tenantId,
a.grid_id
FROM bm_attendance_line a
WHERE a.keeper_id = #{keeperId} AND a.grid_id = #{gridId}

    ${dataScope}


    AND a.attendance_date >= #{startDate}


    AND a.attendance_date <= #{endDate}


    AND a.sign_out_status = #{status}


    AND a.sign_in_status = '3' AND a.sign_out_status = '6'

) t ORDER BY t.`date` DESC, t.type DESC
